kf.fadeOutToRight:
@keyframes fadeOutToRight { 
  0% { opacity: 1; transform: translateX(0px); }
  100% { opacity: 0; transform: translateX(20px); }
}

kf.fadeInFromLeft:
@keyframes fadeInFromLeft { 
