  100% { opacity: 1; transform: translateX(0px); }
}

kf.scale-and-rotate-right:
@keyframes scale-and-rotate-right { 
  0% { scale: 0.8; opacity: 0.75; transform: rotate(-45deg); }
  66% { scale: 1; opacity: 1; }
  100% { scale: 1; opacity: 1; transform: rotate(0deg); }
}

